import{_ as e}from"./chunks/stairs-terms.BigRb0h7.js";import{_ as a,o as s,c as i,a5 as r}from"./chunks/framework.BYXPg_yw.js";const u=JSON.parse('{"title":"Stairs and Steps","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/operation/stairs.md","filePath":"manual/operation/stairs.md","lastUpdated":1792139892000}'),d={name:"manual/operation/stairs.md"};function o(h,t,n,l,c,p){return s(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="stairs-and-steps" tabindex="-1">Stairs and Steps <a class="header-anchor" href="#stairs-and-steps" aria-label="Permalink to &quot;Stairs and Steps&quot;">​</a></h1><p>How high a step RBQ can handle depends on the <strong>gait</strong> you use, on whether the stairs have <strong>risers</strong>, and on how <strong>deep</strong> the treads are compared with the step height. This page gives the limits for each gait and the conditions they hold under. The stair height on the <a href="/RBQ/nightly/manual/product-descriptions/general-specification.html">General Specifications</a> page holds only under these conditions.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>The heights on this page are for stairs that meet the conditions in <a href="#limits">Limits by gait</a>.</p></div></div><h2 id="terms" tabindex="-1">Terms <a class="header-anchor" href="#terms" aria-label="Permalink to &quot;Terms {#terms}&quot;">​</a></h2><figure><img style="max-width:100%;width:min(420px, 100%);height:auto;display:block;margin:1rem auto;" src="'+e+'" alt="Stair dimensions: A step height, B tread depth"><figcaption style="text-align:center;">[ A step height · B tread depth ]</figcaption></figure><table tabindex="0"><thead><tr><th></th><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>A</td><td>Step height</td><td>Vertical distance from one tread to the next. A single curb or ledge counts as one step.</td></tr><tr><td>B</td><td>Tread depth</td><td>Horizontal depth of one tread, from its front edge to its back edge (the riser, if there is one).</td></tr><tr><td></td><td>Riser</td><td>The vertical board that closes the space between two treads.</td></tr><tr><td></td><td>Open-riser stairs</td><td>Stairs without risers, with open gaps between the treads.</td></tr><tr><td></td><td>Grating stairs</td><td>Stairs whose treads are metal grating you can see through.</td></tr></tbody></table><h2 id="gaits" tabindex="-1">Gaits for stairs <a class="header-anchor" href="#gaits" aria-label="Permalink to &quot;Gaits for stairs {#gaits}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You select</th><th>What walks</th><th>Cameras it uses</th></tr></thead><tbody><tr><td><code>STAIRS</code></td><td>The stair gait, made for stairs</td><td>The four depth cameras under the body</td></tr><tr><td><code>WALK</code> with <code>Vision Walk</code> on (default)</td><td>Learned walking</td><td>The same cameras</td></tr></tbody></table><h2 id="limits" tabindex="-1">Limits by gait <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits by gait {#limits}&quot;">​</a></h2><p>Maximum step height on the legged RBQ10.</p><table tabindex="0"><thead><tr><th>Gait</th><th>Solid or grating stairs with risers</th><th>Open-riser stairs</th></tr></thead><tbody><tr><td><code>STAIRS</code></td><td>Up to 20 cm</td><td>Up to 20 cm</td></tr><tr><td><code>WALK</code> (<code>Vision Walk</code> on)</td><td>Up to 25 cm</td><td>Cannot be used</td></tr></tbody></table><ul><li>These heights are set for <strong>stairs whose tread depth (B) equals the step height (A), 1:1</strong>. Stairs with treads deeper than the step height (B &gt; A) can be used up to the same height.</li></ul>',12)])])}const b=a(d,[["render",o]]);export{u as __pageData,b as default};
